ALTER TABLE accepted_job DROP CONSTRAINT IF EXISTS accepted_job_status_known;
ALTER TABLE accepted_job ADD CONSTRAINT accepted_job_status_known CHECK (status IN ('accepted', 'admitted', 'running', 'paused', 'resume-pending', 'succeeded', 'partial', 'failed', 'cancelled', 'terminated')) NOT VALID;
ALTER TABLE accepted_job VALIDATE CONSTRAINT accepted_job_status_known;

ALTER TABLE accepted_job DROP CONSTRAINT IF EXISTS accepted_job_class_known;
ALTER TABLE accepted_job ADD CONSTRAINT accepted_job_class_known CHECK (job_class IN ('short', 'long')) NOT VALID;
ALTER TABLE accepted_job VALIDATE CONSTRAINT accepted_job_class_known;

CREATE OR REPLACE FUNCTION accepted_job_guard_status() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM job_transition WHERE from_status = OLD.status AND to_status = NEW.status
    ) THEN
        RAISE EXCEPTION 'status move % to % is not in job_transition', OLD.status, NEW.status
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

DROP TRIGGER IF EXISTS accepted_job_guard_status ON accepted_job;
CREATE TRIGGER accepted_job_guard_status BEFORE UPDATE OF status ON accepted_job
    FOR EACH ROW WHEN (OLD.status IS DISTINCT FROM NEW.status)
    EXECUTE FUNCTION accepted_job_guard_status();
